 "content": "def transform(grid):
    # The rule uses the four source areas as destinations in a compact layout.
    h, w = len(grid), len(grid[0])
    seen, objects = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            top,left=min(y for y,x in cells),min(x for y,x in cells)
            objects.append((color,top,left,[(y-top,x-left) for y,x in cells]))
    # Example layout sends the upper-left and upper-right motifs to the top row,
    # lower-left and lower-right motifs to the lower row, preserving colors.
    out=[[0]*w for _ in range(h)]
    for color,top,left,shape in objects:
        maxy=max(y for y,x in shape); maxx=max(x for y,x in shape)
        if top < h//2 and left < w//2:
            y0,x0=0,0
        elif top < h//2:
            y0,x0=0,w-1-maxx
        elif left < w//2:
            y0,x0=h-1-maxy,0
        else:
            y0,x0=h-1-maxy,w-1-maxx
        for dy,dx in shape:
            out[y0+dy][x0+dx]=color
    return out
